mapper.select:
select

from sys_address sa
where sa.active = 1
and sa.biz_type = #{request.bizType}

    and sa.tenant_id = #{request.tenantId}

and exists(
select 1 from sys_address_relation sar
where sar.address_id = sa.id
and sar.active = 1
and sar.biz_type = #{request.relationBizType}

    and sar.biz_id in

        #{bizId}


)

    and (sa.title like concat('%', #{request.q}, '%') or sa.details like concat('%', #{request.q}, '%'))

order by sa.updated_at desc
